import { describe, test, expect, vi, beforeEach, afterEach } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import {
  getSessionJSONItem,
  setSessionJSONItem,
  clearSessionJSONItem,
} from '@salesforce/retail-react-app/app/utils/utils';
import { usePendingWishlistItem } from './usePendingWishlistItem';

// Mocked at the same module boundary useWishlistAuthDrawer.test.tsx already mocks
// (@salesforce/retail-react-app/app/utils/utils), for the same reason: a controllable vi.fn()
// per function rather than exercising real window.sessionStorage.
vi.mock('@salesforce/retail-react-app/app/utils/utils', () => ({
  getSessionJSONItem: vi.fn(() => undefined),
  setSessionJSONItem: vi.fn(),
  clearSessionJSONItem: vi.fn(),
}));

const mockGetSessionJSONItem = vi.mocked(getSessionJSONItem);
const mockSetSessionJSONItem = vi.mocked(setSessionJSONItem);
const mockClearSessionJSONItem = vi.mocked(clearSessionJSONItem);

const PRODUCT_ID = 'product-abc';
const OTHER_PRODUCT_ID = 'product-xyz';
const TEN_MINUTES_MS = 10 * 60 * 1000; // well past the 5-minute bound this hook enforces

describe('usePendingWishlistItem', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockGetSessionJSONItem.mockReturnValue(undefined);
  });

  test('a guest is never resumed — onResume is never called while isGuest stays true', () => {
    const onResume = vi.fn();
    const { result, rerender } = renderHook(
      ({ isGuest }) => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest, onResume }),
      {
        initialProps: { isGuest: true },
      },
    );

    act(() => result.current.beginPendingMove());
    rerender({ isGuest: true });

    expect(onResume).not.toHaveBeenCalled();
  });

  test('beginPendingMove persists the intent to session storage, keyed by productId', () => {
    const onResume = vi.fn();
    const { result } = renderHook(() => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest: true, onResume }));

    act(() => result.current.beginPendingMove());

    expect(mockSetSessionJSONItem).toHaveBeenCalledTimes(1);
    const [key, value] = mockSetSessionJSONItem.mock.calls[0];
    expect(key).toBe(`zimmPendingWishlistCartItem:${PRODUCT_ID}`);
    expect(value).toMatchObject({ productId: PRODUCT_ID });
  });

  describe('resume from React state (email-code / create-account auth — the same instance stays mounted)', () => {
    test('a fresh pending item resumes once isGuest flips to false, and both stores are cleared', () => {
      const onResume = vi.fn();
      const { result, rerender } = renderHook(
        ({ isGuest }) => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest, onResume }),
        {
          initialProps: { isGuest: true },
        },
      );

      act(() => result.current.beginPendingMove());
      expect(onResume).not.toHaveBeenCalled();

      rerender({ isGuest: false });

      expect(onResume).toHaveBeenCalledTimes(1);
      expect(mockClearSessionJSONItem).toHaveBeenCalledWith(`zimmPendingWishlistCartItem:${PRODUCT_ID}`);
    });

    test('with no pending item at all, isGuest flipping to false calls neither onResume nor clearSessionJSONItem', () => {
      const onResume = vi.fn();
      const { rerender } = renderHook(
        ({ isGuest }) => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest, onResume }),
        {
          initialProps: { isGuest: true },
        },
      );

      rerender({ isGuest: false });

      expect(onResume).not.toHaveBeenCalled();
      expect(mockClearSessionJSONItem).not.toHaveBeenCalled();
    });
  });

  describe('resume from session storage (Apple/Google redirect — a fresh mount, no prior React state)', () => {
    test('a fresh mount with isGuest already false and a matching stored intent resumes immediately', () => {
      mockGetSessionJSONItem.mockReturnValue({ productId: PRODUCT_ID, timestamp: Date.now() });
      const onResume = vi.fn();

      renderHook(() => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest: false, onResume }));

      expect(onResume).toHaveBeenCalledTimes(1);
      expect(mockClearSessionJSONItem).toHaveBeenCalledWith(`zimmPendingWishlistCartItem:${PRODUCT_ID}`);
    });

    test('a stored intent for a DIFFERENT product is left untouched — not resumed, not cleared', () => {
      mockGetSessionJSONItem.mockReturnValue({ productId: OTHER_PRODUCT_ID, timestamp: Date.now() });
      const onResume = vi.fn();

      renderHook(() => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest: false, onResume }));

      expect(onResume).not.toHaveBeenCalled();
      expect(mockClearSessionJSONItem).not.toHaveBeenCalled();
    });
  });

  describe('a pending item older than 5 minutes (pass criterion 10)', () => {
    test('from session storage: not resumed, but both stores are still cleared', () => {
      mockGetSessionJSONItem.mockReturnValue({ productId: PRODUCT_ID, timestamp: Date.now() - TEN_MINUTES_MS });
      const onResume = vi.fn();

      renderHook(() => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest: false, onResume }));

      expect(onResume).not.toHaveBeenCalled();
      expect(mockClearSessionJSONItem).toHaveBeenCalledWith(`zimmPendingWishlistCartItem:${PRODUCT_ID}`);
    });

    test('from React state: not resumed once isGuest flips false, but both stores are still cleared', () => {
      // Mutation check on the fixture itself: a fresh (non-stale) timestamp on the exact same
      // path DOES resume (proved by the "resume from React state" describe block above), so this
      // failing when the timestamp is swapped for a stale one is a real assertion, not vacuous.
      const onResume = vi.fn();
      const { result, rerender } = renderHook(
        ({ isGuest }) => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest, onResume }),
        {
          initialProps: { isGuest: true },
        },
      );

      act(() => result.current.beginPendingMove());
      // Directly age the in-memory intent's clock reference by controlling Date.now() at the
      // moment the resume effect actually checks freshness, rather than re-implementing
      // beginPendingMove with a hand-set timestamp.
      const dateNowSpy = vi.spyOn(Date, 'now').mockReturnValue(Date.now() + TEN_MINUTES_MS);
      rerender({ isGuest: false });
      dateNowSpy.mockRestore();

      expect(onResume).not.toHaveBeenCalled();
      expect(mockClearSessionJSONItem).toHaveBeenCalledWith(`zimmPendingWishlistCartItem:${PRODUCT_ID}`);
    });
  });

  describe('cross-row isolation — two different products never share one storage slot (rework fix)', () => {
    // The rest of this file's tests use a single mockReturnValue()/toHaveBeenCalledWith() per
    // test, which cannot represent two DIFFERENT keys coexisting at once — exactly the shape of
    // the defect being proven fixed here (row B's write silently clobbering row A's in the one
    // shared slot the hook used to read/write/clear unconditionally). This block backs the same
    // three mocked functions with a small real in-memory key/value store instead, scoped to these
    // tests only via its own beforeEach/afterEach — the outer beforeEach's
    // `mockGetSessionJSONItem.mockReturnValue(undefined)` runs first (outer beforeEach hooks run
    // before inner ones) and is immediately superseded by the mockImplementation below.
    let fakeStore: Record<string, unknown>;

    beforeEach(() => {
      fakeStore = {};
      mockSetSessionJSONItem.mockImplementation((key: string, value: unknown) => {
        fakeStore[key] = value;
      });
      mockGetSessionJSONItem.mockImplementation((key: string) => fakeStore[key]);
      mockClearSessionJSONItem.mockImplementation((key: string) => {
        delete fakeStore[key];
      });
    });

    // Restore the file's plain default-return-value mocks so a custom mockImplementation from
    // this block can never leak into a later test — see this describe's own comment above.
    afterEach(() => {
      mockSetSessionJSONItem.mockReset();
      mockGetSessionJSONItem.mockReset().mockReturnValue(undefined);
      mockClearSessionJSONItem.mockReset();
    });

    test('two guest clicks on two different rows persist under two different keys — the second does not overwrite the first', () => {
      const onResumeA = vi.fn();
      const onResumeB = vi.fn();
      const rowA = renderHook(() =>
        usePendingWishlistItem({ productId: PRODUCT_ID, isGuest: true, onResume: onResumeA }),
      );
      const rowB = renderHook(() =>
        usePendingWishlistItem({ productId: OTHER_PRODUCT_ID, isGuest: true, onResume: onResumeB }),
      );

      act(() => rowA.result.current.beginPendingMove());
      act(() => rowB.result.current.beginPendingMove());

      expect(Object.keys(fakeStore)).toHaveLength(2);
      expect(fakeStore[`zimmPendingWishlistCartItem:${PRODUCT_ID}`]).toMatchObject({ productId: PRODUCT_ID });
      expect(fakeStore[`zimmPendingWishlistCartItem:${OTHER_PRODUCT_ID}`]).toMatchObject({
        productId: OTHER_PRODUCT_ID,
      });
    });

    test('after a simulated page reload (fresh mounts, no prior React state for either row), both resume independently', () => {
      const onResumeA = vi.fn();
      const onResumeB = vi.fn();

      // Guest phase: row A begins a pending move, then (still guest, before any redirect
      // completes) row B does too — the Tester's exact reported sequence.
      const rowA = renderHook(() =>
        usePendingWishlistItem({ productId: PRODUCT_ID, isGuest: true, onResume: onResumeA }),
      );
      act(() => rowA.result.current.beginPendingMove());
      const rowB = renderHook(() =>
        usePendingWishlistItem({ productId: OTHER_PRODUCT_ID, isGuest: true, onResume: onResumeB }),
      );
      act(() => rowB.result.current.beginPendingMove());

      // The redirect reloads the page — both mounted instances (and all React state) are gone.
      rowA.unmount();
      rowB.unmount();

      // Post-redirect: fresh mounts, isGuest already false, nothing left but session storage —
      // mirrors the file's own "resume from session storage" describe block above, run for both
      // rows against the SAME underlying fake store.
      renderHook(() => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest: false, onResume: onResumeA }));
      renderHook(() => usePendingWishlistItem({ productId: OTHER_PRODUCT_ID, isGuest: false, onResume: onResumeB }));

      expect(onResumeA).toHaveBeenCalledTimes(1);
      expect(onResumeB).toHaveBeenCalledTimes(1);
      // Each row cleared only its own key — nothing left over in either slot.
      expect(fakeStore).toEqual({});
    });

    test('the 5-minute staleness bound is judged per-product, independently — a stale row-A intent does not resume while a fresh row-B intent does, in the same store', () => {
      const onResumeA = vi.fn();
      const onResumeB = vi.fn();
      fakeStore[`zimmPendingWishlistCartItem:${PRODUCT_ID}`] = {
        productId: PRODUCT_ID,
        timestamp: Date.now() - TEN_MINUTES_MS,
      };
      fakeStore[`zimmPendingWishlistCartItem:${OTHER_PRODUCT_ID}`] = {
        productId: OTHER_PRODUCT_ID,
        timestamp: Date.now(),
      };

      renderHook(() => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest: false, onResume: onResumeA }));
      renderHook(() => usePendingWishlistItem({ productId: OTHER_PRODUCT_ID, isGuest: false, onResume: onResumeB }));

      expect(onResumeA).not.toHaveBeenCalled();
      expect(onResumeB).toHaveBeenCalledTimes(1);
      // Both cleared regardless of freshness (matches the existing single-product staleness
      // cases above), now proved not to interfere with each other's independent clearing either.
      expect(fakeStore).toEqual({});
    });
  });
});

